                punches[key]["ts"] = to_ts(parse_iso(corr["time"]))
                applied += 1
        elif action == "add":
            if key not in ever:
                ever.add(key)
                punches[key] = {"emp": corr["employee"], "dir": corr["type"].upper(),
                                "ts": to_ts(parse_iso(corr["time"]))}
                applied += 1

    by_emp = {}
    for (site, pid), p in punches.items():
        if p["emp"] in home_zone:
            by_emp.setdefault(p["emp"], []).append((p["ts"], 0 if p["dir"] == "OUT" else 1,
                                                    site, pid, p["dir"]))

    def in_period(ts, emp):
        day = datetime.fromtimestamp(ts, home_zone[emp]).date()
        return day, start <= day <= end

    result = {emp: {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0,
                    "night_minutes": 0, "gross": Decimal(0)} for emp, _ in employees}
    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0,
           "corrections_applied": applied}

    for emp, items in by_emp.items():
        items.sort()
        kept = []
        last = None
        for ts, _, site, pid, direction in items:
            rounded = round_ts(ts, zones[site])
            if last is not None and last[1] == direction and ts - last[0] <= 300:
                if in_period(rounded, emp)[1]:
                    exc["duplicates_dropped"] += 1
                continue
            last = (ts, direction)
            kept.append((rounded, direction, site))

        shifts = []
        pending = None
        for rounded, direction, site in kept:
            if direction == "IN":
                if pending is not None and in_period(pending[0], emp)[1]:
                    exc["open_shifts"] += 1
                pending = (rounded, site)
            else:
                if pending is not None and rounded - pending[0] <= 16 * 3600:
                    shifts.append((pending[0], rounded, pending[1]))
                else:
                    if pending is not None and in_period(pending[0], emp)[1]:
                        exc["open_shifts"] += 1
                    if in_period(rounded, emp)[1]:
                        exc["orphan_outs"] += 1
                pending = None
        if pending is not None and in_period(pending[0], emp)[1]:
            exc["open_shifts"] += 1

        shifts.sort(key=lambda s: s[0])
        day_paid = {}
        week_paid = {}
        total = Decimal(0)
        acc = result[emp]
        for rin, rout, site in shifts:
            day, ok = in_period(rin, emp)
            if not ok:
                continue
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            zone = zones[site]
            night = 0
            for minute in range(rin, rout, 60):
                hour = datetime.fromtimestamp(minute, zone).hour
                if hour >= 22 or hour < 6:
                    night += 1
            night = min(night, paid)
            before = day_paid.get(day, 0)
            daily_ot = max(0, before + paid - 480) - max(0, before - 480)
            day_paid[day] = before + paid
            week = day - timedelta(days=day.weekday())
            wbefore = week_paid.get(week, 0)
            regular_part = paid - daily_ot
            weekly_ot = max(0, wbefore + regular_part - 2400) - max(0, wbefore - 2400)
            week_paid[week] = wbefore + regular_part
            overtime = daily_ot + weekly_ot
            regular = paid - overtime
            rate = Decimal(0)
            for eff, value in rates.get(emp, []):
                if eff <= day:
                    rate = value
            total += rate * (Decimal(regular) + Decimal("1.5") * overtime) / 60
            total += rate * Decimal("0.15") * night / 60
            acc["shifts"] += 1
            acc["paid_minutes"] += paid
            acc["overtime_minutes"] += overtime
            acc["night_minutes"] += night
        acc["gross"] = total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    totals = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0,
              "gross": Decimal(0)}
    out_emps = {}
    for emp, _ in employees:
        values = result[emp]
        for field in totals:
            totals[field] += values[field]
        out_emps[emp] = dict(values, gross=format(values["gross"], ".2f"))
    totals["gross"] = format(totals["gross"], ".2f")
    summary = {"period": {"start": period["start"], "end": period["end"]},
               "employees": out_emps, "exceptions": exc, "totals": totals}
    Path(output_file).parent.mkdir(parents=True, exist_ok=True)
    Path(output_file).write_text(json.dumps(summary, indent=1))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
